import{K as r,a as l,c as i,b as t,k as d,q as n,ac as s}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"Word 基础编辑、段落与页面设置","description":"从空白文档开始设置纸张、页边距、字体、行距、段前段后、缩进、制表位和分页，完成一份规范通知。","frontmatter":{"title":"Word 基础编辑、段落与页面设置","description":"从空白文档开始设置纸张、页边距、字体、行距、段前段后、缩进、制表位和分页，完成一份规范通知。","showdocs":{"topics":[{"id":"office","title":"Office","link":"/topics/office/"}],"kind":"使用指南","scope":"general","audience":"general","group":"工程与工具","seriesTitle":"Office · Word 文档排版","summary":"从空白文档开始设置纸张、页边距、字体、行距、段前段后、缩进、制表位和分页，完成一份规范通知。","status":"active","related":[{"title":"Excel 实战：建立可刷新、可核对的月报","link":"/tools/office/excel/project","kind":"实践案例","scope":"general","audience":"general"},{"title":"Office 常见问题排查与交付检查表","link":"/tools/office/collaboration/troubleshooting","kind":"故障排查","scope":"general","audience":"general"},{"title":"Office 常用快捷键、选择与粘贴技巧","link":"/tools/office/start/shortcuts","kind":"参考资料","scope":"general","audience":"general"},{"title":"Office 综合实战：从数据到报告、演示和会议","link":"/tools/office/collaboration/workflow","kind":"实践案例","scope":"general","audience":"general"},{"title":"Word 实战：制作可维护的项目报告","link":"/tools/office/word/report","kind":"实践案例","scope":"general","audience":"general"}],"prev":false,"next":{"text":"Word 样式、多级编号与自动目录","link":"/tools/office/word/styles"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":false,"next":{"text":"Word 样式、多级编号与自动目录","link":"/tools/office/word/styles"}},"headers":[],"relativePath":"tools/office/word/editing.md","filePath":"tools/office/word/editing.md"}'),h={name:"tools/office/word/editing.md"},g=Object.assign(h,{setup(c){const a={path:"/tools/office/word/editing",app:"Word",title:"排一页不用空格对齐的会议纪要",steps:[{tab:"布局",command:"页边距",setting:"纸张：A4；页边距：普通",anchor:"walkthrough-1"},{tab:"开始",command:"段落",setting:"对齐：左对齐；段后间距：6 磅",anchor:"walkthrough-2"},{tab:"开始",command:"编号",setting:"每个待办一段；需要新页时插入分页符",anchor:"walkthrough-3"}]};return(p,e)=>{const o=r("OfficeGuide");return l(),i("div",null,[e[0]||(e[0]=t("h1",{id:"word-基础编辑、段落与页面设置",tabindex:"-1"},[d("Word 基础编辑、段落与页面设置 "),t("a",{class:"header-anchor",href:"#word-基础编辑、段落与页面设置","aria-label":'Permalink to "Word 基础编辑、段落与页面设置"'},"​")],-1)),e[1]||(e[1]=t("p",null,"本篇制作一份培训通知：包含标题、背景、时间地点、准备事项和落款。先输入内容，再调整结构，最后检查页面；不要边写边用大量空格和空行挤出想要的样子。",-1)),n(o,{guide:a}),e[2]||(e[2]=s('<h2 id="page" tabindex="-1">建立页面与正文 <a class="header-anchor" href="#page" aria-label="Permalink to &quot;建立页面与正文 {#page}&quot;">​</a></h2><ol><li>新建空白文档并保存为 <code>培训通知.docx</code>。</li><li>在“布局 → 大小”选择实际交付的纸张，例如 A4；“方向”选纵向。</li><li>在“页边距”选择常规或输入单位要求的数值。没有规范时可先用默认设置，再根据预览调整。</li><li>输入标题“数据分析工具培训通知”，再分段输入培训目的、时间地点、参加对象和准备事项。</li><li>打开“开始 → 显示/隐藏编辑标记”，检查是否有多余空段落。</li></ol><p>纸张大小和页边距决定可用版心，字体与行距决定文字密度。屏幕缩放比例不会改变打印布局。字号和字体以组织模板、实际阅读距离为准，不把示例设置当成任何正式公文标准。</p><h2 id="paragraph" tabindex="-1">字符格式与段落格式 <a class="header-anchor" href="#paragraph" aria-label="Permalink to &quot;字符格式与段落格式 {#paragraph}&quot;">​</a></h2><p>字符格式作用于选中的文字，如字体、字号、颜色、粗体。段落格式作用于整个段落，如对齐、缩进、行距和段前段后。只选中一个词再点击居中，整个段落都会居中，因为“居中”属于段落属性。</p><p>选中正文，在“开始 → 段落”对话框中设置。例如正文用 11 或 12 磅、1.5 倍行距、段后 6 磅，可以作为普通内部文档的起点；内容拥挤时先检查是否重复设置了行距和段间距。字体不同时，相同磅值看起来也可能有差异。</p><p>中文正文若需要首行缩进，使用“特殊格式 → 首行缩进 → 2 字符”，不要在每段开头手敲两个全角空格。需要悬挂缩进的条目，例如编号后文字换行仍与文字起点对齐，应设置悬挂缩进或使用规范列表。</p><h2 id="breaks" tabindex="-1">换行、换段和换页 <a class="header-anchor" href="#breaks" aria-label="Permalink to &quot;换行、换段和换页 {#breaks}&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>适合用途</th><th>注意事项</th></tr></thead><tbody><tr><td><code>Enter</code></td><td>开始新段落</td><td>会继承或切换到样式定义的下一段样式</td></tr><tr><td><code>Shift+Enter</code></td><td>同一段内换行</td><td>不会形成新的段落，段间距不单独计算</td></tr><tr><td><code>Ctrl+Enter</code></td><td>从新的一页开始</td><td>插入分页符，不能实现独立页码体系</td></tr><tr><td>分节符</td><td>改变页码、方向、页眉等</td><td>见<a href="/tools/office/word/sections">分节教程</a></td></tr></tbody></table><p>如果标题落在页底、正文跑到下一页，可在段落的“换行和分页”设置中使用“与下段同页”。不要对整篇每个段落都启用，否则大段文字可能被连在一起，造成异常留白。“段中不分页”适合较短的完整段落，不一定适合长表格或长正文。</p><h2 id="lists" tabindex="-1">列表与对齐 <a class="header-anchor" href="#lists" aria-label="Permalink to &quot;列表与对齐 {#lists}&quot;">​</a></h2><p>准备事项适合项目符号，执行流程适合编号。选中对应段落后点击项目符号或编号，使用列表缩进控制文字位置；改顺序时让编号自动变化，不手动输入“1、2、3”。多级章节编号应与标题样式关联，见<a href="/tools/office/word/styles">样式与目录</a>。</p><p>日期和落款可使用右对齐段落。需要在同一行放“姓名”和“日期”时，可使用制表位或无边框表格：打开标尺设置对齐位置，用 <code>Tab</code> 跳到该位置。连续空格依赖字体宽度，换电脑或字体后很容易错位。</p><h2 id="problems" tabindex="-1">常见问题 <a class="header-anchor" href="#problems" aria-label="Permalink to &quot;常见问题 {#problems}&quot;">​</a></h2><p>从其他文档粘贴后行距突然变大，先检查带入的样式和段前段后；一行文字之间空隙异常大，检查是否两端对齐且用了手动换行；末尾空白页删不掉，打开编辑标记查看分页符、分节符及表格后的末段标记，确认原因后再处理。</p><p>只想清除局部字符格式时，不要直接清除整篇所有格式；那可能连需要的标题样式也一起清掉。反复出现的同类格式应通过样式管理。</p><h2 id="practice" tabindex="-1">练习与验收 <a class="header-anchor" href="#practice" aria-label="Permalink to &quot;练习与验收 {#practice}&quot;">​</a></h2><p>完成一页培训通知，正文至少三段，准备事项至少三条。修改纸张方向再改回纵向，确认列表仍然对齐；把正文增加一段，确认无需重新敲空行维持布局。导出 PDF 后检查标题、落款和分页。</p><p>参考入口：<a href="https://support.microsoft.com/en-us/word/" target="_blank" rel="noopener noreferrer">Word 帮助与学习</a>。</p><h2 id="walkthrough" tabindex="-1">图示跟做：排一页不用空格对齐的会议纪要 <a class="header-anchor" href="#walkthrough" aria-label="Permalink to &quot;图示跟做：排一页不用空格对齐的会议纪要 {#walkthrough}&quot;">​</a></h2><p>按上方图示切换三个关键步骤；下面保留完整操作和检查结果，便于跟做与回查。请先使用练习副本。</p><h3 id="walkthrough-1" tabindex="-1">第 1 步：先确定页面边界 <a class="header-anchor" href="#walkthrough-1" aria-label="Permalink to &quot;第 1 步：先确定页面边界 {#walkthrough-1}&quot;">​</a></h3><p><strong>定位：布局 → 页边距。</strong></p><p>新建文档，输入会议名称、日期、三项结论和三项待办。在“布局”中将纸张大小设为 A4，页边距选普通。按 Ctrl+Shift+8 显示编辑标记，观察每次 Enter 产生的段落标记；标题和正文分别成段，便于后续统一设置。</p><h3 id="walkthrough-2" tabindex="-1">第 2 步：让间距由段落设置控制 <a class="header-anchor" href="#walkthrough-2" aria-label="Permalink to &quot;第 2 步：让间距由段落设置控制 {#walkthrough-2}&quot;">​</a></h3><p><strong>定位：开始 → 段落。</strong></p><p>选中正文段落，打开“开始 → 段落”组右下角的小箭头，在对话框设置段后 6 磅、合适的行距。把原先用空行制造的间距删掉，再调整一次段后间距，确认所有选中段落一起改变。日期与负责人需要列对齐时，使用表格或制表位。</p><h3 id="walkthrough-3" tabindex="-1">第 3 步：完成列表并核对换页 <a class="header-anchor" href="#walkthrough-3" aria-label="Permalink to &quot;第 3 步：完成列表并核对换页 {#walkthrough-3}&quot;">​</a></h3><p><strong>定位：开始 → 编号。</strong></p><p>选中三项待办，点击编号；在中间新增一项，确认后面的编号自动更新。需要从新页开始时按 Ctrl+Enter，而不是连续回车。最后缩放到整页检查：文字重新增减后，对齐和间距仍然稳定，才说明排版没有依赖空格堆砌。</p><h3 id="walkthrough-check" tabindex="-1">没有得到预期结果时 <a class="header-anchor" href="#walkthrough-check" aria-label="Permalink to &quot;没有得到预期结果时 {#walkthrough-check}&quot;">​</a></h3><p>某一行突然间距很大时，先检查两端对齐、手动换行与段落设置。开启编辑标记能帮助定位隐藏字符；不要通过缩小字体掩盖局部排版问题。</p>',32))])}}});export{u as __pageData,g as default};
